/**
 * PreToolUse hook on Agent|Task: keeps subagent spawns explicit.
 *
 * Denies: a spawn with no `subagent_type`; a `Plan` spawn with no `model`; a spawn with
 * `effort` `max` unless the description or prompt says `owner asked`; a `fork` spawn unless the
 * prompt says `parent context:`. Anything else passes in silence.
 *
 * A speed bump, not a security guard (the owner may ask for max or a fork): any error lets the
 * spawn through. Always exits 0.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const { deny, readPayload } = require('./lib/decision');

try {
  const input = readPayload()?.tool_input;
  if (input && typeof input === 'object') {
    const type = typeof input.subagent_type === 'string' ? input.subagent_type.trim() : '';
    if (!type) {
      deny('Name the agent type (subagent_type): a kit agent (Explore, analyst, implementer, code-reviewer, …) or `fork`.');
    }
    if (type === 'Plan' && !input.model) {
      deny('Plan needs a model: sonnet (opus only for the L challenger, deliver loop.md).');
    }
    const said = (text) => [input.description, input.prompt].some((v) => typeof v === 'string' && v.toLowerCase().includes(text));
    if (String(input.effort ?? '').trim().toLowerCase() === 'max' && !said('owner asked')) {
      deny('effort max only when the owner asked for it: write `owner asked` in the description, else use high.');
    }
    if (type === 'fork' && !(typeof input.prompt === 'string' && input.prompt.toLowerCase().includes('parent context:'))) {
      deny('a fork only when the parent context is needed: state it as `parent context: <why>` in the prompt, else a fresh agent with a brief.');
    }
  }
} catch {
  /* fail open */
}
process.exit(0);
